<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <string>
#include <algorithm>
using namespace std;

int n, t;
string a[30], b[30];
int d1[30][30], d2[30][30];
int dx[] = {0,0,-1,1};
int dy[] = {1,-1,0,0};

struct Edge {
    int a, b, cap, flow;
};
vector<Edge> e;
vector<int> g[1000];
int source, sink;
int dist[1000], ptr[1000], q[1000];

void add_edge(int a, int b, int cap) {
    e.push_back({a,b,cap,0});
    e.push_back({b,a,0,0});
    g[a].push_back(e.size()-2);
    g[b].push_back(e.size()-1);
}

bool ok(int x, int y) { return x>=0 && x<n && y>=0 && y<n; }

void BFS1(int sx, int sy) {
    for (int i=0;i<30;i++) for (int j=0;j<30;j++) d1[i][j]=1e9;
    queue<pair<int,int>> qq;
    qq.push({sx,sy});
    d1[sx][sy]=0;
    while (!qq.empty()) {
        int x=qq.front().first, y=qq.front().second; qq.pop();
        for (int i=0;i<4;i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if (ok(nx,ny) && d1[nx][ny]>=1e9 && b[nx][ny]!='Y') {
                d1[nx][ny]=d1[x][y]+1;
                qq.push({nx,ny});
            }
        }
    }
}

bool bfs() {
    memset(dist,-1,sizeof(dist));
    int qh=0, qt=0;
    q[qt++]=source;
    dist[source]=0;
    while (qh<qt && dist[sink]==-1) {
        int v=q[qh++];
        for (int id : g[v]) {
            int to=e[id].b;
            if (dist[to]==-1 && e[id].flow<e[id].cap) {
                q[qt++]=to;
                dist[to]=dist[v]+1;
            }
        }
    }
    return dist[sink]!=-1;
}

int dfs(int v, int flow) {
    if (!flow) return 0;
    if (v==sink) return flow;
    for (;ptr[v]<(int)g[v].size();ptr[v]++) {
        int id=g[v][ptr[v]], to=e[id].b;
        if (dist[to]!=dist[v]+1) continue;
        int pushed=dfs(to,min(flow,e[id].cap-e[id].flow));
        if (pushed) {
            e[id].flow+=pushed;
            e[id^1].flow-=pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int flow=0;
    while (bfs()) {
        memset(ptr,0,sizeof(ptr));
        while (int pushed=dfs(source,1e9)) flow+=pushed;
    }
    return flow;
}

void BFS2(int sx, int sy) {
    for (int i=0;i<30;i++) for (int j=0;j<30;j++) d2[i][j]=1e9;
    queue<pair<int,int>> qq;
    qq.push({sx,sy});
    d2[sx][sy]=0;
    while (!qq.empty()) {
        int x=qq.front().first, y=qq.front().second; qq.pop();
        if (d2[x][y]>=d1[x][y]) continue;
        for (int i=0;i<4;i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if (ok(nx,ny) && d2[nx][ny]>=1e9 && a[nx][ny]!='Y' && d2[x][y]+1<=d1[nx][ny]) {
                d2[nx][ny]=d2[x][y]+1;
                qq.push({nx,ny});
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin>>n>>t;
    for (int i=0;i<n;i++) cin>>a[i];
    int wx, wy;
    for (int i=0;i<n;i++) {
        cin>>b[i];
        for (int j=0;j<n;j++) {
            if (b[i][j]=='Z') {
                b[i][j]=a[i][j]='Y';
                wx=i; wy=j;
            }
        }
    }
    BFS1(wx,wy);
    source=0; sink=2*n*n+1;
    for (int i=0;i<n;i++) {
        for (int j=0;j<n;j++) {
            if (a[i][j]=='Y') continue;
            int what=i*n+j+1;
            int what2=n*n+i*n+j+1;
            add_edge(source,what,a[i][j]-'0');
            add_edge(what2,sink,b[i][j]-'0');
            BFS2(i,j);
            for (int x=0;x<n;x++) {
                for (int y=0;y<n;y++) {
                    if (b[x][y]=='Y' || d2[x][y]>t) continue;
                    add_edge(what,n*n+x*n+y+1,a[i][j]-'0');
                }
            }
        }
    }
    n=2*n*n+5;
    cout<<max_flow()<<endl;
    return 0;
}
